entries[46396] = { ["name"] = "Pfeife des Wolvarwaisenkindes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Kinderwoche\nBenutzen: Mit Rechtsklick das Waisenkind rufen und fortschicken, dessen Beaufsichtigung Ihr während der Kinderwoche übernommen habt." }
entries[46397] = { ["name"] = "Pfeife des Orakelwaisenkindes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Kinderwoche\nBenutzen: Mit Rechtsklick das Waisenkind rufen und fortschicken, dessen Beaufsichtigung Ihr während der Kinderwoche übernommen habt." }
