entries[46803] = { ["name"] = "Rezept: Gewürzbrotfüllung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (1)\nBenutzen: Lehrt Euch, wie man Gewürzbrotfüllung zubereitet.\n\nGewürzbrotfüllung\nBenötigt Pilgerfreudenfest\nBenutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und Trefferwert und Ausdauer werden 1 Stunde lang um [floor(cond([Quellwert]( 90, 15), 90 - 15, 0) * 0.554) + 4] erhöht.\nVerkaufspreis:\nBenötigt Gewürzbrot , Herbstliche Gewürze", ["unresolvedValues"] = true }
entries[46804] = { ["name"] = "Rezept: Kürbiskuchen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (100)\nBenutzen: Lehrt Euch, wie man Kürbiskuchen zubereitet.\n\nKürbiskuchen\nBenötigt Pilgerfreudenfest\nBenutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und 1 Stunde lang Eure Willenskraft und Ausdauer um [floor(cond([Quellwert]( 90, 15), 90 - 15, 0) * 0.554) + 4] erhöht.\nVerkaufspreis:\nBenötigt Reifer Tirisfalkürbis , Honig", ["unresolvedValues"] = true }
entries[46805] = { ["name"] = "Rezept: Moosbeerenchutney", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (160)\nBenutzen: Lehrt Euch, wie man Moosbeerenchutney zubereitet.\n\nMoosbeerenchutney\nBenötigt Pilgerfreudenfest\nBenutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und 1 Stunde lang Eure Zaubermacht um [floor(cond([Quellwert]( 90, 15), 90 - 15, 0) * 0.6616) + 4] und Eure Ausdauer um [floor(cond([Quellwert]( 90, 15), 90 - 15, 0) * 0.554) + 4] erhöht.\nVerkaufspreis:\nBenötigt Säuerliche Moosbeeren vom Südstrom , Honig", ["unresolvedValues"] = true }
entries[46806] = { ["name"] = "Rezept: Kandierte Süßkartoffel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (220)\nBenutzen: Lehrt Euch, wie man kandierte Süßkartoffeln zubereitet.\n\nKandierte Süßkartoffel\nBenötigt Pilgerfreudenfest\nBenutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und Tempo und Ausdauer werden 1 Stunde lang um [floor(cond([Quellwert]( 90, 15), 90 - 15, 0) * 0.8) + 4] erhöht.\nVerkaufspreis:\nBenötigt Süßkartoffel aus Mulgore , Honig , Herbstliche Gewürze", ["unresolvedValues"] = true }
entries[46807] = { ["name"] = "Rezept: Langsam gerösteter Truthahn", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (280)\nBenutzen: Lehrt Euch, wie man langsam gerösteten Truthahn zubereitet.\n\nLangsam gerösteter Truthahn\nBenötigt Pilgerfreudenfest\nBenutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und 1 Stunde lang Eure Angriffskraft um [floor(cond([Quellwert]( 90, 15), 90 - 15, 0) * 1.108) + 8] und Eure Ausdauer um [floor(cond([Quellwert]( 90, 15), 90 - 15, 0) * 0.554) + 4] erhöht.\nVerkaufspreis:\nBenötigt Wilder Truthahn , Honig (2), Herbstliche Gewürze", ["unresolvedValues"] = true }
